-- TES-001..038.  Treasury facts are written only through the service-role
-- command boundary. Amounts are numeric(28,8), supplied and returned as text.
insert into public.access_control_permissions(code,resource,action,description) values
 ('treasury.read','treasury','read','Consultar tesorería'),('treasury.manage','treasury','manage','Administrar maestros de tesorería'),
 ('treasury.post','treasury','post','Registrar movimientos de tesorería'),('treasury.reverse','treasury','reverse','Reversar movimientos de tesorería'),
 ('treasury.checks','treasury','checks','Emitir y entregar cheques'),('treasury.reconcile','treasury','reconcile','Conciliar cuentas bancarias'),
 ('treasury.tax.configure','treasury','tax_configure','Configurar impuesto al débito bancario')
on conflict(code) do update set description=excluded.description;
insert into public.organization_role_permissions(role_id,permission_code)
select r.id,p.code from public.organization_roles r cross join (select unnest(array['treasury.read','treasury.manage','treasury.post','treasury.reverse','treasury.checks','treasury.reconcile','treasury.tax.configure']) code) p
where r.code in ('owner','admin') and r.status='active' on conflict do nothing;

