create table public.shared_treasury_collection_allocations (tenant_id uuid not null references public.tenants(id), id text not null, company_id text not null, deposit_id text not null, collection_id text not null, amount numeric(28,8) not null check(amount>0), currency varchar(3) not null check(currency~'^[A-Z]{3}$'), primary key(tenant_id,deposit_id,collection_id), unique(tenant_id,id), foreign key(tenant_id,company_id) references public.shared_companies(tenant_id,id), foreign key(tenant_id,deposit_id) references public.shared_treasury_deposits(tenant_id,id), foreign key(tenant_id,collection_id) references public.shared_sales_receivable_payments(tenant_id,id));create or replace function public.treasury_reject_reserved_sales_collection_reversal() returns trigger language plpgsql security definer set search_path=public as $$
begin
 if exists(select 1 from public.shared_treasury_collection_allocations a where a.tenant_id=new.tenant_id and a.collection_id=new.payment_id) then raise exception 'SALES_RECEIVABLE_PAYMENT_RESERVED_FOR_DEPOSIT'; end if;
 return new;
end $$;
