create index shared_treasury_collection_allocation_claim_idx on public.shared_treasury_collection_allocations(tenant_id,collection_id);
create or replace function public.treasury_reserve_collection_allocation() returns trigger language plpgsql security definer set search_path=public as $$
declare v_received numeric(28,8); v_currency text; v_reserved numeric(28,8);
begin
 select p.received_amount,p.received_currency_code into v_received,v_currency from public.shared_sales_receivable_payments p join public.shared_sales_receivables r on r.tenant_id=p.tenant_id and r.id=p.receivable_id where p.tenant_id=new.tenant_id and p.id=new.collection_id and r.company_id=new.company_id for update of p;
 if not found or v_currency<>new.currency then raise exception 'TREASURY_SOURCE_ALREADY_APPLIED'; end if;
 select coalesce(sum(a.amount),0) into v_reserved from public.shared_treasury_collection_allocations a where a.tenant_id=new.tenant_id and a.collection_id=new.collection_id;
 if v_reserved+new.amount>v_received then raise exception 'TREASURY_SOURCE_ALREADY_APPLIED'; end if;
 return new;
end $$;
create trigger treasury_reserve_collection_allocation before insert on public.shared_treasury_collection_allocations for each row execute function public.treasury_reserve_collection_allocation();
