create or replace function public.treasury_mark_reconciled_check() returns trigger language plpgsql security definer set search_path=public as $$
declare v_source_type text; v_source_id text; v_updated integer;
begin
 select source_type,source_id into v_source_type,v_source_id from public.shared_treasury_ledger_entries where tenant_id=new.tenant_id and id=new.ledger_entry_id;
 if v_source_type='check' then
  if new.status='active' then
   update public.shared_treasury_checks set status='cleared',version=version+1 where tenant_id=new.tenant_id and id=v_source_id and status in('issued','delivered');
   get diagnostics v_updated=row_count;
   if v_updated=0 then raise exception 'TREASURY_CONFLICT'; end if;
  elsif tg_op='UPDATE' and old.status='active' and new.status='undone' then
   update public.shared_treasury_checks c set status=case when (select event_type from public.shared_treasury_check_delivery_events d where d.tenant_id=c.tenant_id and d.check_id=c.id order by d.created_at desc,d.id desc limit 1)='delivered' then 'delivered' else 'issued' end,version=version+1 where c.tenant_id=new.tenant_id and c.id=v_source_id and c.status='cleared';
   get diagnostics v_updated=row_count;
   if v_updated=0 then raise exception 'TREASURY_CONFLICT'; end if;
  end if;
 end if;
 return new;
end $$;
create trigger treasury_mark_check_cleared after insert or update of status on public.shared_treasury_reconciliation_matches for each row execute function public.treasury_mark_reconciled_check();
