create or replace function public.treasury_reject_executed_payment_order_mutation() returns trigger language plpgsql security definer set search_path=public as $$
begin
 if exists(select 1 from public.shared_treasury_payment_executions e where e.tenant_id=old.tenant_id and e.payment_order_id=old.id) then raise exception 'PAYMENT_ORDER_EXECUTED'; end if;
 return old;
end $$;
create trigger treasury_reject_executed_payment_order_mutation before update or delete on public.shared_payment_orders for each row execute function public.treasury_reject_executed_payment_order_mutation();
-- Direct tables are opaque to every API role. The command function holds all grants.
do $$ declare r record; begin
 for r in select tablename from pg_tables where schemaname='public' and tablename like 'shared_treasury_%' loop execute format('alter table public.%I enable row level security',r.tablename); end loop;
end $$;
do $$ declare r record; begin
 for r in select tablename from pg_tables where schemaname='public' and tablename like 'shared_treasury_%' loop execute format('revoke all on table public.%I from anon,authenticated,service_role',r.tablename); end loop;
end $$;
