create or replace function public.treasury_money_valid(p jsonb) returns boolean language sql immutable as $$
 select p is not null and jsonb_typeof(p)='object' and (p->>'amount')~'^[0-9]+([.][0-9]{1,8})?$' and (p->>'amount')::numeric>0 and (p->>'currency')~'^[A-Z]{3}$' and p ? 'operationalValue' and (p->'operationalValue'->>'amount')~'^[0-9]+([.][0-9]{1,8})?$' and (p->'operationalValue'->>'rate')~'^[0-9]+([.][0-9]{1,8})?$' and (p->'operationalValue'->>'rate')::numeric>0 and p->'operationalValue'->>'baseCurrency'='VES'
$$;
create or replace function public.treasury_tolerance_valid(p jsonb) returns boolean language sql immutable as $$
 select coalesce(p is not null and jsonb_typeof(p)='object' and (p->>'amount')~'^(0|[1-9][0-9]{0,19})([.][0-9]{1,8})?$' and (p->>'amount')::numeric>=0 and (p->>'currency')~'^[A-Z]{3}$',false)
$$;
-- PostgreSQL jsonb normally serializes numeric columns as JSON numbers. Treasury
-- transports every numeric business value as a string so JavaScript consumers
-- cannot silently round a monetary amount before the monetary package parses it.
create or replace function public.treasury_exact_json(p_value jsonb) returns jsonb language plpgsql immutable as $$
declare v_key text; v_value jsonb; v_result jsonb;
begin
 case jsonb_typeof(p_value)
 when 'number' then return to_jsonb(p_value#>>'{}');
 when 'array' then select coalesce(jsonb_agg(public.treasury_exact_json(value)),'[]'::jsonb) into v_result from jsonb_array_elements(p_value); return v_result;
 when 'object' then v_result:='{}'::jsonb; for v_key,v_value in select key,value from jsonb_each(p_value) loop v_result:=v_result||jsonb_build_object(v_key,public.treasury_exact_json(v_value)); end loop; return v_result;
 else return p_value;
 end case;
end $$;
create or replace function public.treasury_insert_ledger(p_tenant uuid,p_company text,p_command jsonb,p_id text,p_account jsonb,p_direction text,p_money jsonb,p_operational_date date,p_value_date date,p_concept text,p_movement_type text,p_source jsonb default null,p_reversal_of text default null) returns void language plpgsql security definer set search_path=public as $$
begin
 if not public.treasury_money_valid(p_money) or p_direction not in('credit','debit') or p_account->>'kind' not in('cash_box','bank_account') then raise exception 'TREASURY_INVALID'; end if;
 if p_account->>'kind'='cash_box' then
   perform 1 from public.shared_treasury_cash_boxes where tenant_id=p_tenant and company_id=p_company and id=p_account->>'id' and currency=p_money->>'currency' and status='active';
 else
   perform 1 from public.shared_treasury_bank_accounts where tenant_id=p_tenant and company_id=p_company and id=p_account->>'id' and currency=p_money->>'currency' and status='active';
 end if;
 if not found then raise exception 'TREASURY_NOT_FOUND'; end if;
 if p_movement_type='deposit' and jsonb_array_length(coalesce(p_command->'collectionAllocations','[]'::jsonb))>0 then
   if (select coalesce(sum((value->'amount'->>'amount')::numeric),0) from jsonb_array_elements(p_command->'collectionAllocations'))<>(p_money->>'amount')::numeric
     or exists(select 1 from jsonb_array_elements(p_command->'collectionAllocations') where value->'amount'->>'currency'<>p_money->>'currency') then raise exception 'TREASURY_INVALID'; end if;
 end if;
 insert into public.shared_treasury_ledger_entries(tenant_id,id,company_id,account_kind,account_id,direction,movement_type,amount,currency,operational_amount,operational_rate,operational_source,operational_as_of,operational_policy_version,operational_rounding,operational_date,value_date,concept,source_type,source_id,source_line_id,reversal_of_id)
 values(p_tenant,p_id,p_company,p_account->>'kind',p_account->>'id',p_direction,p_movement_type,(p_money->>'amount')::numeric,p_money->>'currency',(p_money->'operationalValue'->>'amount')::numeric,(p_money->'operationalValue'->>'rate')::numeric,p_money->'operationalValue'->>'source',(p_money->'operationalValue'->>'asOf')::date,p_money->'operationalValue'->>'policyVersion',p_money->'operationalValue'->>'rounding',p_operational_date,p_value_date,p_concept,p_source->>'type',p_source->>'id',p_source->>'lineId',p_reversal_of);
end $$;
create or replace function public.treasury_assess_bank_debit_tax() returns trigger language plpgsql security definer set search_path=public as $$
declare v_rule public.shared_treasury_idb_rules%rowtype; v_tax numeric(28,8); v_balance numeric; v_allow_overdraft boolean;
begin
 if new.status<>'posted' or new.account_kind<>'bank_account' or new.direction<>'debit' or new.movement_type not in('bank_debit','check_issue') then return new; end if;
 select * into v_rule from public.shared_treasury_idb_rules where tenant_id=new.tenant_id and company_id=new.company_id and active and new.operational_date>=effective_from and (effective_to is null or new.operational_date<=effective_to) and new.currency=base_currency and subject_types ? new.movement_type order by effective_from desc,id desc limit 1;
 if not found then raise exception 'TREASURY_TAX_POLICY_MISSING'; end if;
 if exists(select 1 from public.shared_treasury_idb_rules where tenant_id=new.tenant_id and company_id=new.company_id and active and new.operational_date>=effective_from and (effective_to is null or new.operational_date<=effective_to) and new.currency=base_currency and subject_types ? new.movement_type offset 1) then raise exception 'TREASURY_CONFLICT'; end if;
 v_tax:=round(new.amount*v_rule.rate/100,8);
 insert into public.shared_treasury_idb_assessments(tenant_id,id,company_id,ledger_entry_id,policy_id,policy_version,effective_from,effective_to,rate_percent,taxable_amount,tax_amount,currency,rounding,created_at) values(new.tenant_id,new.id,new.company_id,new.id,v_rule.id,v_rule.version,v_rule.effective_from,v_rule.effective_to,v_rule.rate,new.amount,v_tax,new.currency,v_rule.rounding,now());
 if v_tax>0 then
  select allow_overdraft into v_allow_overdraft from public.shared_treasury_bank_accounts where tenant_id=new.tenant_id and id=new.account_id and company_id=new.company_id for update;
  select coalesce(sum(case when direction='credit' then amount else -amount end),0) into v_balance from public.shared_treasury_ledger_entries where tenant_id=new.tenant_id and company_id=new.company_id and account_kind='bank_account' and account_id=new.account_id and currency=new.currency and status in('posted','reversed');
  if v_balance<v_tax and not coalesce(v_allow_overdraft,false) then raise exception 'TREASURY_INSUFFICIENT_FUNDS'; end if;
  insert into public.shared_treasury_ledger_entries(tenant_id,id,company_id,account_kind,account_id,direction,movement_type,amount,currency,operational_amount,operational_rate,operational_source,operational_as_of,operational_policy_version,operational_rounding,operational_date,value_date,concept,source_type,source_id,source_line_id)
  values(new.tenant_id,new.id||':tax',new.company_id,'bank_account',new.account_id,'debit','bank_debit_tax',v_tax,new.currency,v_tax,1,'identity',new.operational_as_of,v_rule.version::text,v_rule.rounding,new.operational_date,new.value_date,'Bank debit tax','bank_debit_tax',new.id,'tax');
  update public.shared_treasury_bank_accounts set version=version+1,updated_at=now() where tenant_id=new.tenant_id and id=new.account_id;
 end if;
 return new;
end $$;
create trigger treasury_assess_bank_debit_tax after insert or update of status on public.shared_treasury_ledger_entries for each row execute function public.treasury_assess_bank_debit_tax();

create or replace function public.treasury_run_automatic_reconciliation(p_tenant uuid,p_company text,p_command jsonb) returns void language plpgsql security definer set search_path=public as $$
declare v_rule public.shared_treasury_reconciliation_rules%rowtype; v_stmt record; v_candidates jsonb; v_best_score numeric; v_best_id text; v_best_count integer; v_competing_lines integer; v_results jsonb:='[]'::jsonb;
begin
 perform 1 from public.shared_treasury_bank_accounts where tenant_id=p_tenant and id=p_command->>'bankAccountId' and company_id=p_company and status='active' for update;
 if not found then raise exception 'TREASURY_NOT_FOUND'; end if;
 select * into v_rule from public.shared_treasury_reconciliation_rules where tenant_id=p_tenant and id=p_command->>'ruleSetId' and company_id=p_company and bank_account_id=p_command->>'bankAccountId' and active_from<=(p_command->>'asOf')::date and ((p_command->>'kind'='preview_reconciliation_rule' and version=(p_command->>'ruleVersion')::integer and not active) or (p_command->>'kind'<>'preview_reconciliation_rule' and active)) for share;
 if not found then raise exception 'TREASURY_NOT_FOUND'; end if;
 insert into public.shared_treasury_reconciliation_runs(tenant_id,id,company_id,bank_account_id,rule_set_id,rule_version,run_type,as_of,results) values(p_tenant,p_command->>'runId',p_company,p_command->>'bankAccountId',p_command->>'ruleSetId',v_rule.version,case when p_command->>'kind'='preview_reconciliation_rule' then 'preview' else 'execution' end,(p_command->>'asOf')::date,'[]'::jsonb);
 for v_stmt in select s.* from public.shared_treasury_statement_lines s join public.shared_treasury_statements st on st.tenant_id=s.tenant_id and st.id=s.statement_id where s.tenant_id=p_tenant and st.company_id=p_company and st.bank_account_id=p_command->>'bankAccountId' and st.status='open' and s.value_date<=(p_command->>'asOf')::date and not exists(select 1 from public.shared_treasury_reconciliation_matches m where m.tenant_id=s.tenant_id and m.statement_line_id=s.id and m.status='active') order by s.value_date,s.id for update of s loop
  select coalesce(jsonb_agg(jsonb_build_object('id',c.id,'score',c.score) order by c.score desc,c.id),'[]'::jsonb) into v_candidates from (
   select e.id,((case when lower(btrim(coalesce(e.source_id,e.concept)))=lower(btrim(v_stmt.reference)) then v_rule.reference_weight else 0 end)+((v_rule.date_window_days-abs(e.value_date-v_stmt.value_date)+1)*v_rule.date_weight))::numeric score
   from public.shared_treasury_ledger_entries e where e.tenant_id=p_tenant and e.company_id=p_company and e.account_kind='bank_account' and e.account_id=p_command->>'bankAccountId' and e.status in('posted','reversed') and e.direction=v_stmt.direction and e.currency=v_stmt.currency and abs(e.amount-v_stmt.amount)<=v_rule.tolerance_amount and abs(e.value_date-v_stmt.value_date)<=v_rule.date_window_days and e.value_date<=(p_command->>'asOf')::date and not exists(select 1 from public.shared_treasury_reconciliation_matches m where m.tenant_id=e.tenant_id and m.ledger_entry_id=e.id and m.status='active') and not exists(select 1 from jsonb_array_elements(v_results) prior where prior->>'state'='matched' and prior->>'ledgerEntryId'=e.id)
  ) c where c.score>0;
  v_best_score:=nullif(v_candidates->0->>'score','')::numeric; v_best_id:=v_candidates->0->>'id';
  if v_best_id is null then
   v_results:=v_results||jsonb_build_array(jsonb_build_object('statementLineId',v_stmt.id,'state','unmatched','reason','no_candidate'));
  else
   select count(*) into v_best_count from jsonb_array_elements(v_candidates) x where (x->>'score')::numeric=v_best_score;
   if v_best_count=1 then
   select count(*) into v_competing_lines from public.shared_treasury_statement_lines s2 join public.shared_treasury_statements st2 on st2.tenant_id=s2.tenant_id and st2.id=s2.statement_id join public.shared_treasury_ledger_entries e on e.tenant_id=s2.tenant_id and e.id=v_best_id where s2.tenant_id=p_tenant and st2.company_id=p_company and st2.bank_account_id=p_command->>'bankAccountId' and st2.status='open' and s2.id<>v_stmt.id and s2.value_date<=(p_command->>'asOf')::date and not exists(select 1 from public.shared_treasury_reconciliation_matches m where m.tenant_id=s2.tenant_id and m.statement_line_id=s2.id and m.status='active') and not exists(select 1 from jsonb_array_elements(v_results) prior where prior->>'state'='matched' and prior->>'statementLineId'=s2.id) and s2.direction=e.direction and s2.currency=e.currency and abs(s2.amount-e.amount)<=v_rule.tolerance_amount and abs(s2.value_date-e.value_date)<=v_rule.date_window_days and ((case when lower(btrim(coalesce(e.source_id,e.concept)))=lower(btrim(s2.reference)) then v_rule.reference_weight else 0 end)+((v_rule.date_window_days-abs(e.value_date-s2.value_date)+1)*v_rule.date_weight))::numeric=v_best_score;
   else v_competing_lines:=0; end if;
   if v_best_count>1 or v_competing_lines>0 then
    v_results:=v_results||jsonb_build_array(jsonb_build_object('statementLineId',v_stmt.id,'state','ambiguous','candidateLedgerEntryIds',(select coalesce(jsonb_agg(x->>'id' order by x->>'id'),'[]'::jsonb) from jsonb_array_elements(v_candidates) x where (x->>'score')::numeric=v_best_score)));
   else
    if p_command->>'kind'<>'preview_reconciliation_rule' then
     insert into public.shared_treasury_reconciliation_matches(tenant_id,id,company_id,bank_account_id,statement_line_id,ledger_entry_id,match_type,rule_set_id,rule_version,reason,created_by) values(p_tenant,(p_command->>'runId')||':'||v_stmt.id,p_company,p_command->>'bankAccountId',v_stmt.id,v_best_id,'automatic',p_command->>'ruleSetId',v_rule.version,'unique best amount, direction, currency, date and reference score',(p_command->>'actorId')::uuid);
    end if;
    v_results:=v_results||jsonb_build_array(jsonb_build_object('statementLineId',v_stmt.id,'ledgerEntryId',v_best_id,'state','matched','score',v_best_score));
   end if;
  end if;
 end loop;
 update public.shared_treasury_reconciliation_runs set results=v_results where tenant_id=p_tenant and id=p_command->>'runId';
end $$;

create or replace function public.shared_treasury_execute_command(p_scope jsonb,p_command jsonb) returns jsonb
language plpgsql security definer set search_path=public as $$
declare v_tenant uuid; v_kind text; v_idem text; v_hash text; v_import_hash text; v_existing_hash text; v_existing_statement text; v_receipt public.shared_treasury_command_receipts%rowtype; v_response jsonb; v_account jsonb; v_money jsonb; v_id text; v_version integer; v_source_version integer; v_balance numeric; v_delta numeric; v_currency text; v_first_number bigint; v_last_number bigint; v_next_number bigint; v_allow_overdraft boolean; v_source_allow_overdraft boolean; v_line jsonb; v_source jsonb; v_entry public.shared_treasury_ledger_entries%rowtype; v_tax_entry public.shared_treasury_ledger_entries%rowtype; v_check public.shared_treasury_checks%rowtype; v_order public.shared_payment_orders%rowtype; v_rule public.shared_treasury_reconciliation_rules%rowtype; v_tax_rule public.shared_treasury_idb_rules%rowtype; v_match public.shared_treasury_reconciliation_matches%rowtype; v_count integer:=0;
begin
 if p_scope is null or p_command is null or jsonb_typeof(p_scope)<>'object' or jsonb_typeof(p_command)<>'object' or p_scope->>'tenantId' is null or p_scope->>'organizationId' is null or p_scope->>'companyId' is null or p_scope->>'actorId' is null then raise exception 'TREASURY_INVALID'; end if;
 v_tenant:=public.assert_user_security_access((p_scope->>'actorId')::uuid,(p_scope->>'organizationId')::uuid,p_scope->>'companyId','treasury.read');
 if v_tenant::text is distinct from p_scope->>'tenantId' then raise exception 'TREASURY_FORBIDDEN'; end if;
 v_kind:=p_command->>'kind'; v_idem:=nullif(btrim(p_command->>'idempotencyKey'),''); if v_kind is null or v_idem is null or length(v_idem)>256 or nullif(btrim(p_command->>'correlationId'),'') is null then raise exception 'TREASURY_INVALID'; end if;
 perform public.set_operational_audit_context((p_scope->>'actorId')::uuid,(p_scope->>'organizationId')::uuid,p_scope->>'companyId',null,null);
 if v_kind in ('create_cash_box','create_bank','create_bank_account','create_beneficiary','create_checkbook','configure_reconciliation','activate_reconciliation_rule') then perform public.assert_user_security_access((p_scope->>'actorId')::uuid,(p_scope->>'organizationId')::uuid,p_scope->>'companyId','treasury.manage'); else perform public.assert_user_security_access((p_scope->>'actorId')::uuid,(p_scope->>'organizationId')::uuid,p_scope->>'companyId',case when v_kind in('configure_bank_debit_tax_policy','exclude_bank_debit_tax_operation') then 'treasury.tax.configure' when v_kind in('reverse_ledger_entry','undo_check_delivery','undo_reconciliation_match') then 'treasury.reverse' when v_kind in('issue_check','record_check_delivery') then 'treasury.checks' when v_kind like '%reconciliation%' or v_kind='import_bank_statement' then 'treasury.reconcile' else 'treasury.post' end); end if;
 -- Authorize the actual operation before consulting an idempotency receipt;
 -- otherwise a read-only actor who knows a key could replay a write response.
 perform public.set_operational_audit_context((p_scope->>'actorId')::uuid,(p_scope->>'organizationId')::uuid,p_scope->>'companyId',null,null);
 if v_kind in ('create_cash_box','create_bank','create_bank_account','create_beneficiary','create_checkbook','configure_reconciliation','activate_reconciliation_rule') then perform public.assert_user_security_access((p_scope->>'actorId')::uuid,(p_scope->>'organizationId')::uuid,p_scope->>'companyId','treasury.manage'); else perform public.assert_user_security_access((p_scope->>'actorId')::uuid,(p_scope->>'organizationId')::uuid,p_scope->>'companyId',case when v_kind in('configure_bank_debit_tax_policy','exclude_bank_debit_tax_operation') then 'treasury.tax.configure' when v_kind in('reverse_ledger_entry','undo_check_delivery','undo_reconciliation_match') then 'treasury.reverse' when v_kind in('issue_check','record_check_delivery') then 'treasury.checks' when v_kind like '%reconciliation%' or v_kind='import_bank_statement' then 'treasury.reconcile' else 'treasury.post' end); end if;
 v_hash:=encode(digest(jsonb_strip_nulls(p_command)::text,'sha256'),'hex');
 -- Serialize the first writer too. A row lock only protects an already-created
 -- receipt and permits two initial requests to mutate before the unique insert.
 perform pg_advisory_xact_lock(hashtextextended(v_tenant::text||':'||(p_scope->>'companyId')||':'||v_idem,0));
 select * into v_receipt from public.shared_treasury_command_receipts where tenant_id=v_tenant and company_id=p_scope->>'companyId' and idempotency_key=v_idem for update;
 if found then if v_receipt.intent_hash<>v_hash then raise exception 'TREASURY_IDEMPOTENCY_CONFLICT'; end if; return v_receipt.response || jsonb_build_object('replayed',true); end if;
 case v_kind
 when 'create_cash_box' then
  v_id:=p_command->>'cashBoxId'; if v_id is null or p_command->>'code' is null or p_command->>'name' is null or p_command->>'currency' !~ '^[A-Z]{3}$' then raise exception 'TREASURY_INVALID'; end if;
  insert into public.shared_treasury_cash_boxes(tenant_id,id,company_id,code,name,currency,responsible_actor_id) values(v_tenant,v_id,p_scope->>'companyId',btrim(p_command->>'code'),btrim(p_command->>'name'),p_command->>'currency',(p_command->>'responsibleActorId')::uuid);
  v_response:=jsonb_build_object('commandId',v_id,'replayed',false,'affectedIds',jsonb_build_array(v_id),'versions',jsonb_build_object(v_id,1));
 when 'create_bank' then
  v_id:=p_command->>'bankId'; if v_id is null or p_command->>'code' is null or p_command->>'name' is null or p_command->>'countryCode' !~ '^[A-Z]{2}$' then raise exception 'TREASURY_INVALID'; end if;
  insert into public.shared_treasury_banks values(v_tenant,v_id,p_scope->>'companyId',btrim(p_command->>'code'),btrim(p_command->>'name'),p_command->>'countryCode',1,now()); v_response:=jsonb_build_object('commandId',v_id,'replayed',false,'affectedIds',jsonb_build_array(v_id),'versions',jsonb_build_object(v_id,1));
 when 'create_bank_account' then
  v_id:=p_command->>'bankAccountId'; if v_id is null or p_command->>'bankId' is null or p_command->>'currency' !~ '^[A-Z]{3}$' or nullif(btrim(p_command->>'accountNumber'),'') is null then raise exception 'TREASURY_INVALID'; end if;
  perform 1 from public.shared_treasury_banks where tenant_id=v_tenant and id=p_command->>'bankId' and company_id=p_scope->>'companyId'; if not found then raise exception 'TREASURY_NOT_FOUND'; end if;
  insert into public.shared_treasury_bank_accounts(tenant_id,id,company_id,bank_id,currency,holder_name,account_number,account_number_hash,allow_overdraft) values(v_tenant,v_id,p_scope->>'companyId',p_command->>'bankId',p_command->>'currency',btrim(p_command->>'holderName'),p_command->>'accountNumber',encode(digest(p_command->>'accountNumber','sha256'),'hex'),coalesce((p_command->>'allowOverdraft')::boolean,false)); v_response:=jsonb_build_object('commandId',v_id,'replayed',false,'affectedIds',jsonb_build_array(v_id),'versions',jsonb_build_object(v_id,1));
 when 'create_beneficiary' then
  v_id:=p_command->>'beneficiaryId'; if v_id is null or nullif(btrim(p_command->>'legalName'),'') is null then raise exception 'TREASURY_INVALID'; end if;
  insert into public.shared_treasury_beneficiaries(tenant_id,id,company_id,legal_name,tax_identifier) values(v_tenant,v_id,p_scope->>'companyId',btrim(p_command->>'legalName'),nullif(btrim(p_command->>'taxIdentifier'),''));
  for v_line in select value from jsonb_array_elements(coalesce(p_command->'bankDetails','[]'::jsonb)) loop insert into public.shared_treasury_beneficiary_bank_details values(v_tenant,v_line->>'id',v_id,v_line->>'bankId',v_line->>'currency',v_line->>'accountNumber',v_line->>'accountHolder'); end loop;
