  if p_command->>'method'<>'check' then if v_account->>'kind'='cash_box' then update public.shared_treasury_cash_boxes set version=version+1 where tenant_id=v_tenant and id=v_account->>'id'; else update public.shared_treasury_bank_accounts set version=version+1 where tenant_id=v_tenant and id=v_account->>'id'; end if; end if;
