  insert into public.shared_treasury_statements(tenant_id,id,company_id,bank_account_id,period_start,period_end,external_reference,import_fingerprint) values(v_tenant,v_id,p_scope->>'companyId',p_command->>'bankAccountId',(p_command->>'periodStart')::date,(p_command->>'periodEnd')::date,p_command->>'externalReference',v_import_hash) on conflict(tenant_id,bank_account_id,external_reference) do nothing returning id into v_existing_statement;
  if v_existing_statement is null then
   select id,import_fingerprint into v_existing_statement,v_existing_hash from public.shared_treasury_statements where tenant_id=v_tenant and bank_account_id=p_command->>'bankAccountId' and external_reference=p_command->>'externalReference' for update;
