   for v_line in select value from jsonb_array_elements(p_command->'lines') loop
    insert into public.shared_treasury_statement_lines(tenant_id,id,statement_id,bank_account_id,external_id,value_date,direction,amount,currency,reference,description) values(v_tenant,v_line->>'lineId',v_existing_statement,p_command->>'bankAccountId',v_line->>'externalId',(v_line->>'valueDate')::date,v_line->>'direction',(v_line->'money'->>'amount')::numeric,v_line->'money'->>'currency',v_line->>'reference',v_line->>'description');
   end loop;
   v_response:=jsonb_build_object('commandId',v_existing_statement,'replayed',false,'affectedIds',jsonb_build_array(v_existing_statement),'versions',jsonb_build_object(v_existing_statement,1));
  end if;
 when 'configure_reconciliation' then
  v_id:=p_command->>'ruleSetId'; if v_id is null or coalesce((p_command->>'expectedVersion')::integer,-1)<0 or not public.treasury_tolerance_valid(p_command->'amountTolerance') or (p_command->>'dateWindowDays')::integer not between 0 and 365 or (p_command->>'referenceWeight')::numeric<0 or (p_command->>'dateWeight')::numeric<0 or (p_command->>'referenceWeight')::numeric+(p_command->>'dateWeight')::numeric<=0 then raise exception 'TREASURY_INVALID'; end if;
  select currency into v_id from public.shared_treasury_bank_accounts where tenant_id=v_tenant and id=p_command->>'bankAccountId' and company_id=p_scope->>'companyId' and status='active' for update; if v_id is null then raise exception 'TREASURY_NOT_FOUND'; end if; if v_id<>p_command->'amountTolerance'->>'currency' then raise exception 'TREASURY_INVALID'; end if;
  v_id:=p_command->>'ruleSetId'; v_version:=coalesce((p_command->>'expectedVersion')::integer,0);
  if (select coalesce(max(version),0) from public.shared_treasury_reconciliation_rules where tenant_id=v_tenant and id=v_id)<>v_version or exists(select 1 from public.shared_treasury_reconciliation_rules where tenant_id=v_tenant and id=v_id and not active and version>coalesce((select max(version) from public.shared_treasury_reconciliation_rules where tenant_id=v_tenant and id=v_id and active),0)) then raise exception 'TREASURY_CONFLICT'; end if;
  insert into public.shared_treasury_reconciliation_rules(tenant_id,id,company_id,bank_account_id,active_from,date_window_days,tolerance_amount,currency,reference_weight,date_weight,version,active) values(v_tenant,v_id,p_scope->>'companyId',p_command->>'bankAccountId',(p_command->>'activeFrom')::date,(p_command->>'dateWindowDays')::integer,(p_command->'amountTolerance'->>'amount')::numeric,p_command->'amountTolerance'->>'currency',(p_command->>'referenceWeight')::numeric,(p_command->>'dateWeight')::numeric,v_version+1,false);
  v_response:=jsonb_build_object('commandId',v_id,'replayed',false,'affectedIds',jsonb_build_array(v_id),'versions',jsonb_build_object(v_id,v_version+1));
 when 'preview_reconciliation_rule' then
  if (p_command->>'ruleVersion')::integer is null then raise exception 'TREASURY_INVALID'; end if;
  perform public.treasury_run_automatic_reconciliation(v_tenant,p_scope->>'companyId',jsonb_build_object('kind','preview_reconciliation_rule','runId',p_command->>'previewId','bankAccountId',p_command->>'bankAccountId','ruleSetId',p_command->>'ruleSetId','ruleVersion',p_command->>'ruleVersion','asOf',p_command->>'asOf'));
  v_response:=jsonb_build_object('commandId',p_command->>'previewId','replayed',false,'affectedIds',jsonb_build_array(p_command->>'previewId'),'versions',jsonb_build_object(p_command->>'previewId',1));
