  v_response:=jsonb_build_object('commandId',v_id,'replayed',false,'affectedIds',jsonb_build_array(v_id),'versions',jsonb_build_object(v_id,v_version));
 when 'reconcile_manually' then
  perform 1 from public.shared_treasury_statement_lines where tenant_id=v_tenant and id=p_command->>'statementLineId' and version=(p_command->>'expectedStatementLineVersion')::integer for update; if not found then raise exception 'TREASURY_CONFLICT'; end if; perform 1 from public.shared_treasury_ledger_entries where tenant_id=v_tenant and id=p_command->>'ledgerEntryId' and version=(p_command->>'expectedLedgerEntryVersion')::integer for update; if not found or exists(select 1 from public.shared_treasury_reconciliation_matches where tenant_id=v_tenant and status='active' and (statement_line_id=p_command->>'statementLineId' or ledger_entry_id=p_command->>'ledgerEntryId')) then raise exception 'TREASURY_CONFLICT'; end if; if not exists(select 1 from public.shared_treasury_statement_lines s join public.shared_treasury_statements st on st.tenant_id=s.tenant_id and st.id=s.statement_id join public.shared_treasury_ledger_entries e on e.tenant_id=s.tenant_id where s.tenant_id=v_tenant and s.id=p_command->>'statementLineId' and st.company_id=p_scope->>'companyId' and st.bank_account_id=p_command->>'bankAccountId' and st.status='open' and e.id=p_command->>'ledgerEntryId' and e.company_id=p_scope->>'companyId' and e.status in('posted','reversed') and e.account_kind='bank_account' and e.account_id=p_command->>'bankAccountId' and s.currency=e.currency and s.direction=e.direction and s.amount=e.amount) then raise exception 'TREASURY_INVALID'; end if; insert into public.shared_treasury_reconciliation_matches(tenant_id,id,company_id,bank_account_id,statement_line_id,ledger_entry_id,match_type,rule_set_id,rule_version,reason,created_by) values(v_tenant,p_command->>'matchId',p_scope->>'companyId',p_command->>'bankAccountId',p_command->>'statementLineId',p_command->>'ledgerEntryId','manual',null,null,p_command->>'reason',(p_scope->>'actorId')::uuid); v_response:=jsonb_build_object('commandId',p_command->>'matchId','replayed',false,'affectedIds',jsonb_build_array(p_command->>'matchId'),'versions',jsonb_build_object(p_command->>'matchId',1));
 when 'undo_reconciliation_match' then
  select m.* into v_match from public.shared_treasury_reconciliation_matches m join public.shared_treasury_statement_lines s on s.tenant_id=m.tenant_id and s.id=m.statement_line_id join public.shared_treasury_statements st on st.tenant_id=s.tenant_id and st.id=s.statement_id where m.tenant_id=v_tenant and m.id=p_command->>'matchId' and m.company_id=p_scope->>'companyId' and m.status='active' and st.status='open' for update of m,st;
  if not found or v_match.version<>(p_command->>'expectedVersion')::integer then raise exception 'TREASURY_CONFLICT'; end if;
