  v_response:=jsonb_build_object('commandId',v_match.id,'replayed',false,'affectedIds',jsonb_build_array(v_match.id,v_match.statement_line_id,v_match.ledger_entry_id),'versions',jsonb_build_object(v_match.id,v_match.version+1));
 when 'run_automatic_reconciliation' then
  perform public.treasury_run_automatic_reconciliation(v_tenant,p_scope->>'companyId',jsonb_set(p_command,'{actorId}',to_jsonb(p_scope->>'actorId'))); v_response:=jsonb_build_object('commandId',p_command->>'runId','replayed',false,'affectedIds',jsonb_build_array(p_command->>'runId'),'versions',jsonb_build_object(p_command->>'runId',1));
 when 'close_reconciliation' then
  select version into v_version from public.shared_treasury_statements where tenant_id=v_tenant and id=p_command->>'statementId' and bank_account_id=p_command->>'bankAccountId' and company_id=p_scope->>'companyId' and status='open' for update; if v_version is null then raise exception 'TREASURY_NOT_FOUND'; end if; if v_version<>(p_command->>'expectedStatementVersion')::integer then raise exception 'TREASURY_CONFLICT'; end if; if (exists(select 1 from public.shared_treasury_statement_lines s where s.tenant_id=v_tenant and s.statement_id=p_command->>'statementId' and not exists(select 1 from public.shared_treasury_reconciliation_matches m where m.tenant_id=s.tenant_id and m.statement_line_id=s.id and m.status='active')) or exists(select 1 from public.shared_treasury_statements st join public.shared_treasury_ledger_entries e on e.tenant_id=st.tenant_id and e.company_id=st.company_id and e.account_kind='bank_account' and e.account_id=st.bank_account_id where st.tenant_id=v_tenant and st.id=p_command->>'statementId' and e.status in('posted','reversed') and e.value_date between st.period_start and st.period_end and not exists(select 1 from public.shared_treasury_reconciliation_matches m where m.tenant_id=e.tenant_id and m.ledger_entry_id=e.id and m.status='active'))) and nullif(btrim(p_command->>'differenceExplanation'),'') is null then raise exception 'TREASURY_RECONCILIATION_INCOMPLETE'; end if; update public.shared_treasury_statements set status='closed',closed_at=(p_command->>'closedAt')::timestamptz,difference_explanation=nullif(btrim(p_command->>'differenceExplanation'),''),version=version+1 where tenant_id=v_tenant and id=p_command->>'statementId'; v_response:=jsonb_build_object('commandId',p_command->>'closeId','replayed',false,'affectedIds',jsonb_build_array(p_command->>'closeId',p_command->>'statementId'),'versions',jsonb_build_object(p_command->>'statementId',v_version+1));
