  if not found then raise exception 'TREASURY_NOT_FOUND'; end if;
  if v_entry.amount<>(p_command->'priorOperationalValue'->>'amount')::numeric or v_entry.currency<>p_command->'currentOperationalValue'->>'currency' or v_entry.amount<>(p_command->'currentOperationalValue'->>'amount')::numeric or p_command->'priorOperationalValue'->'operationalValue'->>'baseCurrency'<>'VES' or p_command->'currentOperationalValue'->'operationalValue'->>'baseCurrency'<>'VES' then raise exception 'TREASURY_INVALID'; end if;
