 when 'configure_bank_debit_tax_policy' then
  perform public.assert_user_security_access((p_scope->>'actorId')::uuid,(p_scope->>'organizationId')::uuid,p_scope->>'companyId','treasury.tax.configure'); v_id:=p_command->>'policyId'; if v_id is null or p_command->>'baseCurrency' !~ '^[A-Z]{3}$' or (p_command->>'ratePercent') !~ '^[0-9]+(\.[0-9]{1,8})?$' or (p_command->>'ratePercent')::numeric<0 or p_command->>'rounding'<>'half_up' or nullif(p_command->>'legalBasis','') is null or nullif(p_command->>'approvalReference','') is null or jsonb_typeof(p_command->'subjectTypes')<>'array' or jsonb_array_length(p_command->'subjectTypes')=0 then raise exception 'TREASURY_INVALID'; end if; v_version:=coalesce((p_command->>'expectedVersion')::integer,0); if v_version>0 then select * into v_tax_rule from public.shared_treasury_idb_rules where tenant_id=v_tenant and id=v_id order by version desc limit 1 for update; if v_tax_rule.version is distinct from v_version then raise exception 'TREASURY_CONFLICT'; end if; if (p_command->>'effectiveFrom')::date<v_tax_rule.effective_from then raise exception 'TREASURY_CONFLICT'; elsif (p_command->>'effectiveFrom')::date=v_tax_rule.effective_from then update public.shared_treasury_idb_rules set active=false where tenant_id=v_tenant and id=v_id and effective_from=v_tax_rule.effective_from and active; elsif v_tax_rule.effective_to is null or v_tax_rule.effective_to>=(p_command->>'effectiveFrom')::date then update public.shared_treasury_idb_rules set effective_to=(p_command->>'effectiveFrom')::date-1 where tenant_id=v_tenant and id=v_id and version=v_tax_rule.version; end if; end if; insert into public.shared_treasury_idb_rules(tenant_id,id,company_id,effective_from,effective_to,rate,base_currency,rounding,legal_basis,approval_reference,subject_types,version) values(v_tenant,v_id,p_scope->>'companyId',(p_command->>'effectiveFrom')::date,nullif(p_command->>'effectiveTo','')::date,(p_command->>'ratePercent')::numeric,p_command->>'baseCurrency',p_command->>'rounding',p_command->>'legalBasis',p_command->>'approvalReference',p_command->'subjectTypes',v_version+1); v_response:=jsonb_build_object('commandId',v_id,'replayed',false,'affectedIds',jsonb_build_array(v_id),'versions',jsonb_build_object(v_id,v_version+1));
