  select * into v_tax_entry from public.shared_treasury_ledger_entries where tenant_id=v_tenant and reversal_of_id is null and movement_type='bank_debit_tax' and source_id=v_entry.id for update;
  if found then
   insert into public.shared_treasury_ledger_entries(tenant_id,id,company_id,account_kind,account_id,direction,movement_type,amount,currency,operational_amount,operational_rate,operational_source,operational_as_of,operational_policy_version,operational_rounding,operational_date,value_date,concept,source_type,source_id,source_line_id,reversal_of_id) values(v_tax_entry.tenant_id,p_command->>'exclusionId'||':refund',v_tax_entry.company_id,v_tax_entry.account_kind,v_tax_entry.account_id,'credit','bank_debit_tax_exclusion',v_tax_entry.amount,v_tax_entry.currency,v_tax_entry.operational_amount,v_tax_entry.operational_rate,v_tax_entry.operational_source,v_tax_entry.operational_as_of,v_tax_entry.operational_policy_version,v_tax_entry.operational_rounding,current_date,current_date,'Refund of excluded bank debit tax','bank_debit_tax_exclusion',p_command->>'exclusionId',v_entry.id,v_tax_entry.id);
