 end case;
 insert into public.shared_treasury_command_receipts values(v_tenant,p_scope->>'companyId',v_idem,v_hash,v_response,now()); return v_response;
exception when unique_violation then raise exception 'TREASURY_CONFLICT'; when foreign_key_violation then raise exception 'TREASURY_NOT_FOUND'; when invalid_text_representation then raise exception 'TREASURY_INVALID'; end $$;

revoke all on function public.shared_treasury_execute_command(jsonb,jsonb),public.treasury_insert_ledger(uuid,text,jsonb,text,jsonb,text,jsonb,date,date,text,text,jsonb,text),public.treasury_money_valid(jsonb),public.treasury_tolerance_valid(jsonb),public.treasury_run_automatic_reconciliation(uuid,text,jsonb),public.treasury_mark_reconciled_check() from public,anon,authenticated,service_role;
grant execute on function public.shared_treasury_execute_command(jsonb,jsonb) to service_role;

create or replace function public.shared_treasury_query(p_scope jsonb,p_query jsonb) returns jsonb
language plpgsql stable security definer set search_path=public as $$
declare v_tenant uuid; v_kind text; v_limit integer; v_offset integer; v_account text; v_rows jsonb; v_total bigint;
begin
 if p_scope is null or p_query is null or p_scope->>'tenantId' is null or p_scope->>'organizationId' is null or p_scope->>'companyId' is null or p_scope->>'actorId' is null then raise exception 'TREASURY_INVALID'; end if;
 if p_query?'search' and (nullif(btrim(p_query->>'search'),'') is null or length(p_query->>'search')>120) then raise exception 'TREASURY_INVALID'; end if;
 v_tenant:=public.assert_user_security_access((p_scope->>'actorId')::uuid,(p_scope->>'organizationId')::uuid,p_scope->>'companyId','treasury.read'); if v_tenant::text is distinct from p_scope->>'tenantId' then raise exception 'TREASURY_FORBIDDEN'; end if;
 v_kind:=p_query->>'kind'; v_limit:=coalesce((p_query->>'pageSize')::integer,50); v_offset:=(coalesce((p_query->>'page')::integer,1)-1)*v_limit; if v_limit<1 or v_limit>(case when v_kind='treasury_report' then 10000 else 500 end) or v_offset<0 then raise exception 'TREASURY_INVALID'; end if;
 case v_kind
 when 'get_payment_order_execution' then
  select count(*) into v_total from public.shared_treasury_payment_executions where tenant_id=v_tenant and company_id=p_scope->>'companyId' and payment_order_id=p_query->>'paymentOrderId';
  select coalesce(jsonb_agg(jsonb_build_object('paymentId',id,'paymentOrderId',payment_order_id,'amount',amount::text,'currency',currency,'occurredOn',created_at::date::text,'ledgerEntryId',ledger_entry_id)),'[]'::jsonb) into v_rows from public.shared_treasury_payment_executions where tenant_id=v_tenant and company_id=p_scope->>'companyId' and payment_order_id=p_query->>'paymentOrderId';
 when 'list_cash_boxes' then select count(*) into v_total from public.shared_treasury_cash_boxes where tenant_id=v_tenant and company_id=p_scope->>'companyId' and (p_query->>'cashBoxId' is null or id=p_query->>'cashBoxId') and (p_query->>'currency' is null or currency=p_query->>'currency') and (p_query->>'status' is null or (p_query->>'status'='active' and status='active') or (p_query->>'status'='inactive' and status='archived')); select coalesce(jsonb_agg(to_jsonb(x) order by x.code,x.id),'[]') into v_rows from (select id,code,name,currency,responsible_actor_id,status,version from public.shared_treasury_cash_boxes where tenant_id=v_tenant and company_id=p_scope->>'companyId' and (p_query->>'cashBoxId' is null or id=p_query->>'cashBoxId') and (p_query->>'currency' is null or currency=p_query->>'currency') and (p_query->>'status' is null or (p_query->>'status'='active' and status='active') or (p_query->>'status'='inactive' and status='archived')) order by code,id offset v_offset limit v_limit) x;
 when 'list_banks' then
  select count(*) into v_total from public.shared_treasury_banks where tenant_id=v_tenant and company_id=p_scope->>'companyId' and (p_query->>'search' is null or position(lower(p_query->>'search') in lower(code||' '||name||' '||country_code))>0);
  select coalesce(jsonb_agg(jsonb_build_object('id',id,'code',code,'name',name,'countryCode',country_code,'version',version) order by code,id),'[]'::jsonb) into v_rows from (select * from public.shared_treasury_banks where tenant_id=v_tenant and company_id=p_scope->>'companyId' and (p_query->>'search' is null or position(lower(p_query->>'search') in lower(code||' '||name||' '||country_code))>0) order by code,id offset v_offset limit v_limit)x;
 when 'list_beneficiaries' then
  if p_query->>'status' is not null and p_query->>'status' not in('active','inactive') then raise exception 'TREASURY_INVALID'; end if;
  select count(*) into v_total from public.shared_treasury_beneficiaries where tenant_id=v_tenant and company_id=p_scope->>'companyId' and (p_query->>'status' is null or (p_query->>'status'='active' and status='active') or (p_query->>'status'='inactive' and status='archived')) and (p_query->>'search' is null or position(lower(p_query->>'search') in lower(legal_name||' '||coalesce(tax_identifier,'')))>0);
  select coalesce(jsonb_agg(jsonb_build_object('id',x.id,'legalName',x.legal_name,'taxIdentifier',x.tax_identifier,'status',case when x.status='archived' then 'inactive' else x.status end,'bankDetails',x.bank_details) order by lower(x.legal_name),x.id),'[]'::jsonb) into v_rows from (select b.id,b.legal_name,b.tax_identifier,b.status,b.version,(select coalesce(jsonb_agg(jsonb_build_object('id',d.id,'bankId',d.bank_id,'currency',d.currency,'accountNumberMasked',case when length(d.account_number)<=4 then repeat('*',length(d.account_number)) else repeat('*',length(d.account_number)-4)||right(d.account_number,4) end,'accountHolder',d.account_holder) order by d.id),'[]'::jsonb) from public.shared_treasury_beneficiary_bank_details d where d.tenant_id=b.tenant_id and d.beneficiary_id=b.id) bank_details from public.shared_treasury_beneficiaries b where b.tenant_id=v_tenant and b.company_id=p_scope->>'companyId' and (p_query->>'status' is null or (p_query->>'status'='active' and b.status='active') or (p_query->>'status'='inactive' and b.status='archived')) and (p_query->>'search' is null or position(lower(p_query->>'search') in lower(b.legal_name||' '||coalesce(b.tax_identifier,'')))>0) order by lower(b.legal_name),b.id offset v_offset limit v_limit)x;
 when 'list_bank_accounts' then select count(*) into v_total from public.shared_treasury_bank_accounts where tenant_id=v_tenant and company_id=p_scope->>'companyId' and (p_query->>'bankAccountId' is null or id=p_query->>'bankAccountId') and (p_query->>'bankId' is null or bank_id=p_query->>'bankId') and (p_query->>'currency' is null or currency=p_query->>'currency') and (p_query->>'status' is null or (p_query->>'status'='active' and status='active') or (p_query->>'status'='inactive' and status='archived')); select coalesce(jsonb_agg(jsonb_build_object('id',x.id,'bankId',x.bank_id,'currency',x.currency,'holderName',x.holder_name,'accountNumberMasked',case when length(x.account_number)<=4 then repeat('*',length(x.account_number)) else repeat('*',length(x.account_number)-4)||right(x.account_number,4) end,'allowOverdraft',x.allow_overdraft,'status',x.status) order by x.id),'[]') into v_rows from (select * from public.shared_treasury_bank_accounts where tenant_id=v_tenant and company_id=p_scope->>'companyId' and (p_query->>'bankAccountId' is null or id=p_query->>'bankAccountId') and (p_query->>'bankId' is null or bank_id=p_query->>'bankId') and (p_query->>'currency' is null or currency=p_query->>'currency') and (p_query->>'status' is null or (p_query->>'status'='active' and status='active') or (p_query->>'status'='inactive' and status='archived')) order by id offset v_offset limit v_limit)x;
 when 'get_balance' then v_account:=p_query->>'accountId'; select count(*) into v_total from public.shared_treasury_ledger_entries e where e.tenant_id=v_tenant and e.company_id=p_scope->>'companyId' and e.account_kind=p_query->>'accountKind' and e.account_id=v_account and e.value_date<=(p_query->>'asOf')::date and e.status in('posted','reversed'); select jsonb_build_array(jsonb_build_object('accountId',v_account,'accountKind',p_query->>'accountKind','asOf',p_query->>'asOf','currency',currency,'balance',balance::text)) into v_rows from (select currency,sum(case when direction='credit' then amount else -amount end) balance from public.shared_treasury_ledger_entries e where e.tenant_id=v_tenant and e.company_id=p_scope->>'companyId' and e.account_kind=p_query->>'accountKind' and e.account_id=v_account and e.value_date<=(p_query->>'asOf')::date and e.status in('posted','reversed') group by currency)x;
 when 'list_ledger_entries' then v_account:=p_query->>'accountId'; select count(*) into v_total from public.shared_treasury_ledger_entries e where e.tenant_id=v_tenant and e.company_id=p_scope->>'companyId' and e.account_kind=p_query->>'accountKind' and e.account_id=v_account and e.value_date between (p_query->>'from')::date and (p_query->>'to')::date and (p_query->>'status' is null or e.status=p_query->>'status') and (p_query->>'movementType' is null or e.movement_type=p_query->>'movementType') and (p_query->>'sourceType' is null or e.source_type=p_query->>'sourceType') and (p_query->>'responsibleActorId' is null or exists(select 1 from public.shared_operational_audit_trail a where a.tenant_id=e.tenant_id and a.organization_id=(p_scope->>'organizationId')::uuid and a.company_id=e.company_id and a.entity_type='treasury_ledger_entry' and a.entity_id=e.id and a.action='create' and a.actor_id=(p_query->>'responsibleActorId')::uuid)); select coalesce(jsonb_agg(jsonb_build_object('id',x.id,'accountKind',x.account_kind,'accountId',x.account_id,'amount',x.amount::text,'currency',x.currency,'movementType',x.movement_type,'concept',x.concept,'sourceType',x.source_type,'sourceId',x.source_id,'sourceLineId',x.source_line_id,'operationalDate',x.operational_date::text,'valueDate',x.value_date::text,'status',x.status,'responsibleActorId',(select a.actor_id::text from public.shared_operational_audit_trail a where a.tenant_id=x.tenant_id and a.organization_id=(p_scope->>'organizationId')::uuid and a.company_id=x.company_id and a.entity_type='treasury_ledger_entry' and a.entity_id=x.id and a.action='create' order by a.occurred_at,a.id limit 1)) order by x.value_date desc,x.id desc),'[]') into v_rows from (select * from public.shared_treasury_ledger_entries e where e.tenant_id=v_tenant and e.company_id=p_scope->>'companyId' and e.account_kind=p_query->>'accountKind' and e.account_id=v_account and e.value_date between (p_query->>'from')::date and (p_query->>'to')::date and (p_query->>'status' is null or e.status=p_query->>'status') and (p_query->>'movementType' is null or e.movement_type=p_query->>'movementType') and (p_query->>'sourceType' is null or e.source_type=p_query->>'sourceType') and (p_query->>'responsibleActorId' is null or exists(select 1 from public.shared_operational_audit_trail a where a.tenant_id=e.tenant_id and a.organization_id=(p_scope->>'organizationId')::uuid and a.company_id=e.company_id and a.entity_type='treasury_ledger_entry' and a.entity_id=e.id and a.action='create' and a.actor_id=(p_query->>'responsibleActorId')::uuid)) order by value_date desc,id desc offset v_offset limit v_limit)x;
 when 'list_checkbooks' then
  if p_query->>'status' is not null and p_query->>'status' not in('active','closed') then raise exception 'TREASURY_INVALID'; end if;
  select count(*) into v_total from public.shared_treasury_checkbooks where tenant_id=v_tenant and company_id=p_scope->>'companyId' and (p_query->>'bankAccountId' is null or bank_account_id=p_query->>'bankAccountId') and (p_query->>'status' is null or status=p_query->>'status');
  select coalesce(jsonb_agg(jsonb_build_object('id',x.id,'bankAccountId',x.bank_account_id,'firstNumber',x.first_number,'lastNumber',x.last_number,'nextNumber',x.next_number,'status',x.status) order by x.bank_account_id,x.id),'[]'::jsonb) into v_rows from (select * from public.shared_treasury_checkbooks where tenant_id=v_tenant and company_id=p_scope->>'companyId' and (p_query->>'bankAccountId' is null or bank_account_id=p_query->>'bankAccountId') and (p_query->>'status' is null or status=p_query->>'status') order by bank_account_id,id offset v_offset limit v_limit)x;
 when 'list_checks' then select count(*) into v_total from public.shared_treasury_checks where tenant_id=v_tenant and company_id=p_scope->>'companyId' and (p_query->>'bankAccountId' is null or bank_account_id=p_query->>'bankAccountId') and (p_query->>'checkbookId' is null or checkbook_id=p_query->>'checkbookId') and (p_query->>'number' is null or number=(p_query->>'number')::bigint) and (p_query->>'beneficiaryId' is null or beneficiary_id=p_query->>'beneficiaryId') and (p_query->>'from' is null or issue_date>=(p_query->>'from')::date) and (p_query->>'to' is null or issue_date<=(p_query->>'to')::date) and (p_query->>'status' is null or status=p_query->>'status'); select coalesce(jsonb_agg(jsonb_build_object('id',id,'checkbookId',checkbook_id,'bankAccountId',bank_account_id,'number',number,'beneficiaryId',beneficiary_id,'amount',amount::text,'currency',currency,'issueDate',issue_date::text,'status',status,'version',version) order by issue_date desc,number),'[]') into v_rows from (select * from public.shared_treasury_checks where tenant_id=v_tenant and company_id=p_scope->>'companyId' and (p_query->>'bankAccountId' is null or bank_account_id=p_query->>'bankAccountId') and (p_query->>'checkbookId' is null or checkbook_id=p_query->>'checkbookId') and (p_query->>'number' is null or number=(p_query->>'number')::bigint) and (p_query->>'beneficiaryId' is null or beneficiary_id=p_query->>'beneficiaryId') and (p_query->>'from' is null or issue_date>=(p_query->>'from')::date) and (p_query->>'to' is null or issue_date<=(p_query->>'to')::date) and (p_query->>'status' is null or status=p_query->>'status') order by issue_date desc,number offset v_offset limit v_limit)x;
 when 'list_check_deliveries' then
  with rows as (select e.id,e.check_id,e.event_type,e.recipient_name,e.occurred_at,e.reason,e.evidence_reference from public.shared_treasury_check_delivery_events e join public.shared_treasury_checks c on c.tenant_id=e.tenant_id and c.id=e.check_id where e.tenant_id=v_tenant and e.company_id=p_scope->>'companyId' and (p_query->>'bankAccountId' is null or c.bank_account_id=p_query->>'bankAccountId') and (p_query->>'status' is null or e.event_type=p_query->>'status') union all select 'pending:'||c.id,c.id,'pending',null,c.created_at,null,null from public.shared_treasury_checks c where c.tenant_id=v_tenant and c.company_id=p_scope->>'companyId' and c.status='issued' and (p_query->>'bankAccountId' is null or c.bank_account_id=p_query->>'bankAccountId') and (p_query->>'status' is null or p_query->>'status'='pending'))
  select count(*) into v_total from rows;
  with rows as (select e.id,e.check_id,e.event_type,e.recipient_name,e.occurred_at,e.reason,e.evidence_reference from public.shared_treasury_check_delivery_events e join public.shared_treasury_checks c on c.tenant_id=e.tenant_id and c.id=e.check_id where e.tenant_id=v_tenant and e.company_id=p_scope->>'companyId' and (p_query->>'bankAccountId' is null or c.bank_account_id=p_query->>'bankAccountId') and (p_query->>'status' is null or e.event_type=p_query->>'status') union all select 'pending:'||c.id,c.id,'pending',null,c.created_at,null,null from public.shared_treasury_checks c where c.tenant_id=v_tenant and c.company_id=p_scope->>'companyId' and c.status='issued' and (p_query->>'bankAccountId' is null or c.bank_account_id=p_query->>'bankAccountId') and (p_query->>'status' is null or p_query->>'status'='pending')) select coalesce(jsonb_agg(jsonb_build_object('id',x.id,'checkId',x.check_id,'eventType',x.event_type,'recipientName',x.recipient_name,'occurredAt',x.occurred_at::text,'reason',x.reason,'evidenceReference',x.evidence_reference) order by x.occurred_at desc,x.id),'[]'::jsonb) into v_rows from (select * from rows order by occurred_at desc,id offset v_offset limit v_limit)x; when 'list_deposits' then select count(*) into v_total from public.shared_treasury_deposits where tenant_id=v_tenant and company_id=p_scope->>'companyId' and (p_query->>'destinationBankAccountId' is null or destination_bank_account_id=p_query->>'destinationBankAccountId') and (p_query->>'from' is null or deposit_date>=(p_query->>'from')::date) and (p_query->>'to' is null or deposit_date<=(p_query->>'to')::date); select coalesce(jsonb_agg(jsonb_build_object('id',id,'destinationBankAccountId',destination_bank_account_id,'amount',amount::text,'currency',currency,'depositDate',deposit_date::text,'reference',reference) order by deposit_date desc,id desc),'[]') into v_rows from (select * from public.shared_treasury_deposits where tenant_id=v_tenant and company_id=p_scope->>'companyId' and (p_query->>'destinationBankAccountId' is null or destination_bank_account_id=p_query->>'destinationBankAccountId') and (p_query->>'from' is null or deposit_date>=(p_query->>'from')::date) and (p_query->>'to' is null or deposit_date<=(p_query->>'to')::date) order by deposit_date desc,id desc offset v_offset limit v_limit)x;
 when 'list_eligible_collections' then
  select count(*) into v_total from public.shared_sales_receivable_payments p join public.shared_sales_receivables r on r.tenant_id=p.tenant_id and r.id=p.receivable_id where p.tenant_id=v_tenant and r.company_id=p_scope->>'companyId' and r.status<>'cancelled' and (p_query->>'currency' is null or p.received_currency_code=p_query->>'currency') and not exists(select 1 from public.shared_sales_payment_reversals x where x.tenant_id=p.tenant_id and x.payment_id=p.id) and p.received_amount>coalesce((select sum(a.amount) from public.shared_treasury_collection_allocations a where a.tenant_id=p.tenant_id and a.collection_id=p.id),0);
  select coalesce(jsonb_agg(jsonb_build_object('rowKind','eligible_collection','collectionId',x.id,'receivableId',x.receivable_id,'receivedAmount',x.received_amount::text,'reservedAmount',x.reserved_amount::text,'availableAmount',(x.received_amount-x.reserved_amount)::text,'currency',x.received_currency_code,'receivedAt',x.occurred_at::text) order by x.occurred_at,x.id),'[]'::jsonb) into v_rows from (select p.id,p.receivable_id,p.received_amount,p.received_currency_code,p.occurred_at,coalesce((select sum(a.amount) from public.shared_treasury_collection_allocations a where a.tenant_id=p.tenant_id and a.collection_id=p.id),0) reserved_amount from public.shared_sales_receivable_payments p join public.shared_sales_receivables r on r.tenant_id=p.tenant_id and r.id=p.receivable_id where p.tenant_id=v_tenant and r.company_id=p_scope->>'companyId' and r.status<>'cancelled' and (p_query->>'currency' is null or p.received_currency_code=p_query->>'currency') and not exists(select 1 from public.shared_sales_payment_reversals x where x.tenant_id=p.tenant_id and x.payment_id=p.id) and p.received_amount>coalesce((select sum(a.amount) from public.shared_treasury_collection_allocations a where a.tenant_id=p.tenant_id and a.collection_id=p.id),0) order by p.occurred_at,p.id offset v_offset limit v_limit)x; when 'list_reconciliation_items' then
  if p_query->>'state'='reconciled' then select count(*) into v_total from public.shared_treasury_reconciliation_matches where tenant_id=v_tenant and company_id=p_scope->>'companyId' and bank_account_id=p_query->>'bankAccountId' and status='active'; select coalesce(jsonb_agg(jsonb_build_object('id',id,'bankAccountId',bank_account_id,'statementLineId',statement_line_id,'ledgerEntryId',ledger_entry_id,'matchType',match_type,'ruleVersion',rule_version,'createdAt',created_at::text,'createdBy',created_by::text,'version',version,'reason',reason) order by created_at desc),'[]') into v_rows from (select * from public.shared_treasury_reconciliation_matches where tenant_id=v_tenant and company_id=p_scope->>'companyId' and bank_account_id=p_query->>'bankAccountId' and status='active' order by created_at desc offset v_offset limit v_limit)x;
  elsif p_query->>'state'='statement_pending' then select count(*) into v_total from public.shared_treasury_statement_lines s join public.shared_treasury_statements st on st.tenant_id=s.tenant_id and st.id=s.statement_id where s.tenant_id=v_tenant and st.company_id=p_scope->>'companyId' and st.bank_account_id=p_query->>'bankAccountId' and not exists(select 1 from public.shared_treasury_reconciliation_matches m where m.tenant_id=s.tenant_id and m.statement_line_id=s.id and m.status='active'); select coalesce(jsonb_agg(jsonb_build_object('itemKind','statement_line','id',s.id,'bankAccountId',st.bank_account_id,'amount',s.amount::text,'currency',s.currency,'valueDate',s.value_date::text,'reference',s.reference,'ageDays',(current_date-s.value_date),'reason','unmatched') order by s.value_date,s.id),'[]') into v_rows from public.shared_treasury_statement_lines s join public.shared_treasury_statements st on st.tenant_id=s.tenant_id and st.id=s.statement_id where s.tenant_id=v_tenant and st.company_id=p_scope->>'companyId' and st.bank_account_id=p_query->>'bankAccountId' and not exists(select 1 from public.shared_treasury_reconciliation_matches m where m.tenant_id=s.tenant_id and m.statement_line_id=s.id and m.status='active') offset v_offset limit v_limit;
  elsif p_query->>'state'='ledger_pending' then select count(*) into v_total from public.shared_treasury_ledger_entries e where e.tenant_id=v_tenant and e.company_id=p_scope->>'companyId' and e.account_kind='bank_account' and e.account_id=p_query->>'bankAccountId' and e.status in('posted','reversed') and not exists(select 1 from public.shared_treasury_reconciliation_matches m where m.tenant_id=e.tenant_id and m.ledger_entry_id=e.id and m.status='active'); select coalesce(jsonb_agg(jsonb_build_object('itemKind','ledger_entry','id',e.id,'bankAccountId',e.account_id,'amount',e.amount::text,'currency',e.currency,'valueDate',e.value_date::text,'reference',coalesce(e.source_id,e.concept),'ageDays',(current_date-e.value_date),'reason','unmatched') order by e.value_date,e.id),'[]') into v_rows from public.shared_treasury_ledger_entries e where e.tenant_id=v_tenant and e.company_id=p_scope->>'companyId' and e.account_kind='bank_account' and e.account_id=p_query->>'bankAccountId' and e.status in('posted','reversed') and not exists(select 1 from public.shared_treasury_reconciliation_matches m where m.tenant_id=e.tenant_id and m.ledger_entry_id=e.id and m.status='active') offset v_offset limit v_limit;
  elsif p_query->>'state'='ambiguous' then
   select count(*) into v_total from (select distinct on (s.id) s.id,s.value_date from public.shared_treasury_reconciliation_runs r cross join lateral jsonb_array_elements(r.results) item join public.shared_treasury_statement_lines s on s.tenant_id=r.tenant_id and s.id=item->>'statementLineId' where r.tenant_id=v_tenant and r.company_id=p_scope->>'companyId' and r.bank_account_id=p_query->>'bankAccountId' and r.run_type='execution' and item->>'state'='ambiguous' and (p_query->>'from' is null or s.value_date>=(p_query->>'from')::date) and (p_query->>'to' is null or s.value_date<=(p_query->>'to')::date) order by s.id,r.created_at desc)x;
   select coalesce(jsonb_agg(jsonb_build_object('itemKind','statement_line','id',x.id,'bankAccountId',x.bank_account_id,'amount',x.amount::text,'currency',x.currency,'valueDate',x.value_date::text,'reference',x.reference,'ageDays',(current_date-x.value_date),'reason','ambiguous') order by x.value_date,x.id),'[]'::jsonb) into v_rows from (select distinct on (s.id) s.id,st.bank_account_id,s.amount,s.currency,s.value_date,s.reference from public.shared_treasury_reconciliation_runs r cross join lateral jsonb_array_elements(r.results) item join public.shared_treasury_statement_lines s on s.tenant_id=r.tenant_id and s.id=item->>'statementLineId' join public.shared_treasury_statements st on st.tenant_id=s.tenant_id and st.id=s.statement_id where r.tenant_id=v_tenant and r.company_id=p_scope->>'companyId' and r.bank_account_id=p_query->>'bankAccountId' and r.run_type='execution' and item->>'state'='ambiguous' and (p_query->>'from' is null or s.value_date>=(p_query->>'from')::date) and (p_query->>'to' is null or s.value_date<=(p_query->>'to')::date) order by s.id,r.created_at desc offset v_offset limit v_limit)x;
  else raise exception 'TREASURY_INVALID'; end if;
 when 'list_reconciliation_history' then
  select count(*) into v_total from public.shared_treasury_reconciliation_matches m join public.shared_treasury_statement_lines s on s.tenant_id=m.tenant_id and s.id=m.statement_line_id where m.tenant_id=v_tenant and m.company_id=p_scope->>'companyId' and m.bank_account_id=p_query->>'bankAccountId' and (p_query->>'from' is null or s.value_date>=(p_query->>'from')::date) and (p_query->>'to' is null or s.value_date<=(p_query->>'to')::date);
  select coalesce(jsonb_agg(jsonb_build_object('id',x.id,'bankAccountId',x.bank_account_id,'statementLineId',x.statement_line_id,'ledgerEntryId',x.ledger_entry_id,'matchType',x.match_type,'ruleSetId',x.rule_set_id,'ruleVersion',x.rule_version,'reason',x.reason,'status',x.status,'createdAt',x.created_at::text,'createdBy',x.created_by::text,'undoneAt',x.undone_at::text,'undoneBy',x.undone_by::text,'undoReason',x.undo_reason) order by x.created_at desc,x.id desc),'[]'::jsonb) into v_rows from (select m.* from public.shared_treasury_reconciliation_matches m join public.shared_treasury_statement_lines s on s.tenant_id=m.tenant_id and s.id=m.statement_line_id where m.tenant_id=v_tenant and m.company_id=p_scope->>'companyId' and m.bank_account_id=p_query->>'bankAccountId' and (p_query->>'from' is null or s.value_date>=(p_query->>'from')::date) and (p_query->>'to' is null or s.value_date<=(p_query->>'to')::date) order by m.created_at desc,m.id desc offset v_offset limit v_limit)x;
 when 'get_reconciliation_preview' then
  select count(*) into v_total from public.shared_treasury_reconciliation_runs where tenant_id=v_tenant and id=p_query->>'previewId' and company_id=p_scope->>'companyId' and run_type='preview';
  select coalesce(jsonb_agg(jsonb_build_object('rowKind','reconciliation_preview','id',id,'bankAccountId',bank_account_id,'ruleSetId',rule_set_id,'ruleVersion',rule_version,'asOf',as_of::text,'results',results,'createdAt',created_at::text)),'[]'::jsonb) into v_rows from public.shared_treasury_reconciliation_runs where tenant_id=v_tenant and id=p_query->>'previewId' and company_id=p_scope->>'companyId' and run_type='preview';
 when 'list_exchange_differences' then
  select count(*) into v_total from public.shared_treasury_exchange_differences where tenant_id=v_tenant and company_id=p_scope->>'companyId' and (p_query->>'bankAccountId' is null or bank_account_id=p_query->>'bankAccountId') and (p_query->>'from' is null or valuation_date>=(p_query->>'from')::date) and (p_query->>'to' is null or valuation_date<=(p_query->>'to')::date) and (p_query->>'differenceKind' is null or difference_kind=p_query->>'differenceKind');
  select coalesce(jsonb_agg(jsonb_build_object('id',id,'sourceEntryId',source_entry_id,'bankAccountId',bank_account_id,'differenceKind',difference_kind,'valuationDate',valuation_date::text,'nativeAmount',native_amount::text,'currency',currency,'priorVesAmount',prior_ves_amount::text,'currentVesAmount',current_ves_amount::text,'differenceVesAmount',difference_ves_amount::text,'priorRate',prior_rate::text,'currentRate',current_rate::text,'priorPolicyVersion',prior_policy_version,'currentPolicyVersion',current_policy_version) order by valuation_date desc,id desc),'[]'::jsonb) into v_rows from (select * from public.shared_treasury_exchange_differences where tenant_id=v_tenant and company_id=p_scope->>'companyId' and (p_query->>'bankAccountId' is null or bank_account_id=p_query->>'bankAccountId') and (p_query->>'from' is null or valuation_date>=(p_query->>'from')::date) and (p_query->>'to' is null or valuation_date<=(p_query->>'to')::date) and (p_query->>'differenceKind' is null or difference_kind=p_query->>'differenceKind') order by valuation_date desc,id desc offset v_offset limit v_limit)x;
 when 'treasury_report' then
  if p_query->>'report' in ('cash_ledger','bank_ledger') then
   select count(*) into v_total from public.shared_treasury_ledger_entries e where e.tenant_id=v_tenant and e.company_id=p_scope->>'companyId' and e.status in('posted','reversed') and e.value_date between (p_query->>'from')::date and (p_query->>'to')::date and ((p_query->>'report'='cash_ledger' and e.account_kind='cash_box') or (p_query->>'report'='bank_ledger' and e.account_kind='bank_account')) and (p_query->>'accountId' is null or e.account_id=p_query->>'accountId') and (p_query->>'currency' is null or e.currency=p_query->>'currency');
   select coalesce(jsonb_agg(jsonb_build_object('id',x.id,'accountId',x.account_id,'accountKind',x.account_kind,'amount',x.amount::text,'currency',x.currency,'movementType',x.movement_type,'operationalDate',x.operational_date::text,'valueDate',x.value_date::text,'concept',x.concept,'status',x.status,'sourceType',x.source_type,'sourceId',x.source_id) order by x.value_date,x.id),'[]'::jsonb) into v_rows from (select e.* from public.shared_treasury_ledger_entries e where e.tenant_id=v_tenant and e.company_id=p_scope->>'companyId' and e.status in('posted','reversed') and e.value_date between (p_query->>'from')::date and (p_query->>'to')::date and ((p_query->>'report'='cash_ledger' and e.account_kind='cash_box') or (p_query->>'report'='bank_ledger' and e.account_kind='bank_account')) and (p_query->>'accountId' is null or e.account_id=p_query->>'accountId') and (p_query->>'currency' is null or e.currency=p_query->>'currency') order by e.value_date,e.id offset v_offset limit v_limit)x;
  elsif p_query->>'report'='balances' then
   select count(*) into v_total from (select e.account_id,e.account_kind,e.currency from public.shared_treasury_ledger_entries e where e.tenant_id=v_tenant and e.company_id=p_scope->>'companyId' and e.status in('posted','reversed') and e.value_date<=(p_query->>'to')::date and (p_query->>'accountId' is null or e.account_id=p_query->>'accountId') and (p_query->>'currency' is null or e.currency=p_query->>'currency') group by e.account_id,e.account_kind,e.currency)x;
   select coalesce(jsonb_agg(jsonb_build_object('accountId',x.account_id,'accountKind',x.account_kind,'currency',x.currency,'balance',x.balance::text,'asOfDate',(p_query->>'to')) order by x.account_kind,x.account_id,x.currency),'[]'::jsonb) into v_rows from (select e.account_id,e.account_kind,e.currency,sum(case when e.direction='credit' then e.amount else -e.amount end) balance from public.shared_treasury_ledger_entries e where e.tenant_id=v_tenant and e.company_id=p_scope->>'companyId' and e.status in('posted','reversed') and e.value_date<=(p_query->>'to')::date and (p_query->>'accountId' is null or e.account_id=p_query->>'accountId') and (p_query->>'currency' is null or e.currency=p_query->>'currency') group by e.account_id,e.account_kind,e.currency order by e.account_kind,e.account_id,e.currency offset v_offset limit v_limit)x;
  elsif p_query->>'report'='checks' then
   select count(*) into v_total from public.shared_treasury_checks c where c.tenant_id=v_tenant and c.company_id=p_scope->>'companyId' and c.issue_date between (p_query->>'from')::date and (p_query->>'to')::date and (p_query->>'accountId' is null or c.bank_account_id=p_query->>'accountId') and (p_query->>'currency' is null or c.currency=p_query->>'currency');
   select coalesce(jsonb_agg(jsonb_build_object('id',x.id,'checkbookId',x.checkbook_id,'bankAccountId',x.bank_account_id,'number',x.number::text,'beneficiaryId',x.beneficiary_id,'amount',x.amount::text,'currency',x.currency,'issueDate',x.issue_date::text,'status',x.status,'ledgerEntryId',x.ledger_entry_id) order by x.issue_date,x.number),'[]'::jsonb) into v_rows from (select c.* from public.shared_treasury_checks c where c.tenant_id=v_tenant and c.company_id=p_scope->>'companyId' and c.issue_date between (p_query->>'from')::date and (p_query->>'to')::date and (p_query->>'accountId' is null or c.bank_account_id=p_query->>'accountId') and (p_query->>'currency' is null or c.currency=p_query->>'currency') order by c.issue_date,c.number offset v_offset limit v_limit)x;
  elsif p_query->>'report'='deposits' then
   select count(*) into v_total from public.shared_treasury_deposits d where d.tenant_id=v_tenant and d.company_id=p_scope->>'companyId' and d.deposit_date between (p_query->>'from')::date and (p_query->>'to')::date and (p_query->>'accountId' is null or d.destination_bank_account_id=p_query->>'accountId') and (p_query->>'currency' is null or d.currency=p_query->>'currency');
   select coalesce(jsonb_agg(jsonb_build_object('id',x.id,'destinationBankAccountId',x.destination_bank_account_id,'sourceAccountKind',x.source_account_kind,'sourceAccountId',x.source_account_id,'amount',x.amount::text,'currency',x.currency,'depositDate',x.deposit_date::text,'reference',x.reference,'sourceLedgerEntryId',x.source_ledger_entry_id,'destinationLedgerEntryId',x.destination_ledger_entry_id) order by x.deposit_date,x.id),'[]'::jsonb) into v_rows from (select d.* from public.shared_treasury_deposits d where d.tenant_id=v_tenant and d.company_id=p_scope->>'companyId' and d.deposit_date between (p_query->>'from')::date and (p_query->>'to')::date and (p_query->>'accountId' is null or d.destination_bank_account_id=p_query->>'accountId') and (p_query->>'currency' is null or d.currency=p_query->>'currency') order by d.deposit_date,d.id offset v_offset limit v_limit)x;
  elsif p_query->>'report'='payments' then
   select count(*) into v_total from public.shared_treasury_payment_executions p join public.shared_treasury_ledger_entries e on e.tenant_id=p.tenant_id and e.id=p.ledger_entry_id where p.tenant_id=v_tenant and p.company_id=p_scope->>'companyId' and e.value_date between (p_query->>'from')::date and (p_query->>'to')::date and (p_query->>'accountId' is null or p.account_id=p_query->>'accountId') and (p_query->>'currency' is null or p.currency=p_query->>'currency');
   select coalesce(jsonb_agg(jsonb_build_object('paymentId',x.id,'paymentOrderId',x.payment_order_id,'beneficiaryId',x.beneficiary_id,'accountKind',x.account_kind,'accountId',x.account_id,'amount',x.amount::text,'currency',x.currency,'method',x.method,'valueDate',x.value_date::text,'ledgerEntryId',x.ledger_entry_id) order by x.value_date,x.id),'[]'::jsonb) into v_rows from (select p.*,e.value_date from public.shared_treasury_payment_executions p join public.shared_treasury_ledger_entries e on e.tenant_id=p.tenant_id and e.id=p.ledger_entry_id where p.tenant_id=v_tenant and p.company_id=p_scope->>'companyId' and e.value_date between (p_query->>'from')::date and (p_query->>'to')::date and (p_query->>'accountId' is null or p.account_id=p_query->>'accountId') and (p_query->>'currency' is null or p.currency=p_query->>'currency') order by e.value_date,p.id offset v_offset limit v_limit)x;
  elsif p_query->>'report'='reconciliation' then
   select count(*) into v_total from public.shared_treasury_reconciliation_matches m join public.shared_treasury_statement_lines s on s.tenant_id=m.tenant_id and s.id=m.statement_line_id join public.shared_treasury_ledger_entries e on e.tenant_id=m.tenant_id and e.id=m.ledger_entry_id where m.tenant_id=v_tenant and m.company_id=p_scope->>'companyId' and m.status='active' and s.value_date between (p_query->>'from')::date and (p_query->>'to')::date and (p_query->>'accountId' is null or m.bank_account_id=p_query->>'accountId') and (p_query->>'currency' is null or s.currency=p_query->>'currency' or e.currency=p_query->>'currency');
   select coalesce(jsonb_agg(jsonb_build_object('matchId',x.id,'bankAccountId',x.bank_account_id,'statementLineId',x.statement_line_id,'ledgerEntryId',x.ledger_entry_id,'matchType',x.match_type,'ruleSetId',x.rule_set_id,'ruleVersion',x.rule_version,'reason',x.reason,'statementAmount',x.statement_amount::text,'statementCurrency',x.statement_currency,'statementDate',x.statement_date::text,'statementReference',x.statement_reference,'ledgerAmount',x.ledger_amount::text,'ledgerCurrency',x.ledger_currency,'ledgerDate',x.ledger_date::text,'ledgerReference',x.ledger_reference) order by x.statement_date,x.id),'[]'::jsonb) into v_rows from (select m.*,s.amount statement_amount,s.currency statement_currency,s.value_date statement_date,s.reference statement_reference,e.amount ledger_amount,e.currency ledger_currency,e.value_date ledger_date,coalesce(e.source_id,e.concept) ledger_reference from public.shared_treasury_reconciliation_matches m join public.shared_treasury_statement_lines s on s.tenant_id=m.tenant_id and s.id=m.statement_line_id join public.shared_treasury_ledger_entries e on e.tenant_id=m.tenant_id and e.id=m.ledger_entry_id where m.tenant_id=v_tenant and m.company_id=p_scope->>'companyId' and m.status='active' and s.value_date between (p_query->>'from')::date and (p_query->>'to')::date and (p_query->>'accountId' is null or m.bank_account_id=p_query->>'accountId') and (p_query->>'currency' is null or s.currency=p_query->>'currency' or e.currency=p_query->>'currency') order by s.value_date,m.id offset v_offset limit v_limit)x;
  else raise exception 'TREASURY_INVALID'; end if;
 else raise exception 'TREASURY_INVALID'; end case;
 return jsonb_build_object('items',coalesce(v_rows,'[]'::jsonb),'total',coalesce(v_total,0),'page',v_offset/v_limit+1,'pageSize',v_limit,'asOf',statement_timestamp()::text);
exception when invalid_text_representation then raise exception 'TREASURY_INVALID'; end $$;
revoke all on function public.shared_treasury_query(jsonb,jsonb),public.treasury_exact_json(jsonb) from public,anon,authenticated,service_role;
grant execute on function public.shared_treasury_query(jsonb,jsonb) to service_role;
